<template><section class="container page"><div class="breadcrumb">首页　/　商品分类 <span v-if="active">/　{{active.name}}</span></div><div class="category-layout"><aside class="category-side"><h3>全部商品分类</h3><router-link v-for="c in categories" :key="c.id" :to="`/category/${c.id}`" :class="{active:c.id===id}">{{c.icon}}　{{c.name}} <span>›</span></router-link><div class="side-note">鲜选承诺<br/><b>不新鲜，无理由退换</b></div></aside><div class="category-content"><div class="category-title"><div><span class="eyebrow">FRESH MARKET</span><h1>{{active?.name || '全部商品'}}</h1><p>精选当季新鲜食材，为你每日更新。</p></div><div class="sort-tabs"><button :class="{active:sort==='hot'}" @click="sort='hot'">人气</button><button :class="{active:sort==='price'}" @click="sort='price'">价格</button><button :class="{active:sort==='new'}" @click="sort='new'">最新</button></div></div><div class="filter-bar"><span>共 {{shown.length}} 件商品</span><label>配送时效 <select><option>不限</option><option>1小时达</option></select></label><label>价格区间 <select><option>全部价格</option><option>¥0-30</option><option>¥30-60</option></select></label></div><div class="product-grid"><ProductCard v-for="p in shown" :key="p.id" :product="p" /></div><div v-if="!shown.length" class="empty">没有找到相关商品，换个关键词试试吧。</div></div></div></section></template>
<script setup>import { computed, ref } from 'vue'; import { useRoute } from 'vue-router'; import { categories, products } from '../data'; import ProductCard from '../components/ProductCard.vue'; const route=useRoute(); const sort=ref('hot'); const id=computed(()=>route.params.id); const active=computed(()=>categories.find(c=>c.id===id.value)); const shown=computed(()=>{let list=products.filter(p=>!id.value||p.category===id.value); if(route.query.q) list=list.filter(p=>p.name.includes(route.query.q)||p.origin.includes(route.query.q)); if(sort.value==='price') return [...list].sort((a,b)=>a.price-b.price); if(sort.value==='new') return [...list].reverse(); return [...list].sort((a,b)=>b.sales-a.sales)})</script>
